-- B31P Q04-A 第二步：近 365 天（[采集时刻-365 天, 采集时刻)，数据库本地时间）按模板 id 的 COL_SUMMARY 实例计数。各模板总行数不超过约 1.2 万，单次查询即可，不再分批。只出计数与窗口边界，不含实例标识。one_evidence_ro（ADR-0037 第 7 项）。
SET LOCK_TIMEOUT 1000;
SELECT s.TEMPLETE_ID AS template_id, COUNT_BIG(*) AS instance_count_365d, CONVERT(varchar(19), DATEADD(day, -365, GETDATE()), 120) AS window_start, CONVERT(varchar(19), GETDATE(), 120) AS as_of_db_local
  FROM [a8_db].dbo.COL_SUMMARY AS s
 WHERE DB_NAME() = N'a8_db' AND s.TEMPLETE_ID IN (-803037765431705053, 16074125293700, 16486247748910, 16620851075370, 2916490644621970991, 5324409057402766767, 5779151688961574431, 6389177723207763537, 7187395059800230659, 8339262726610963687, 9068384877204753833) AND s.CREATE_DATE >= DATEADD(day, -365, GETDATE()) AND s.CREATE_DATE < GETDATE()
 GROUP BY s.TEMPLETE_ID ORDER BY s.TEMPLETE_ID OPTION (MAXDOP 1);
